    /** The node's own class; Id::None for a null node. */
    Id id() const { return m_id; }

    /** The node as a T, or null if it is not one. */
    template <class T> T *as() const {
        static_assert(NodeKindAlwaysFalse<T>::value,
            "NodeKind::as<T>: T is not an AST class");
        return 0;
    }

    template <class T> bool is() const { return as<T>() != 0; }

    /** dynamic_cast<T *>(n), for an AST node `n`. */
    template <class T, class N> static T *cast(N *n) {
        return NodeKind(n).as<T>();
    }

    /** dynamic_cast<const T *>(n). Classifying does not modify `n`. */
    template <class T, class N> static const T *cast(const N *n) {
        return NodeKind(const_cast<N *>(n)).as<T>();
    }

